// Sliding Window — O(n)
let minPrice = Infinity;
let maxProfit = 0;

for (let i = 0; i < prices.length; i++) {
  let price = prices[i];
  if (price < minPrice) {
    minPrice = price;
    console.log(`New min price: ${minPrice}`);
  } else {
    let profit = price - minPrice;
    if (profit > maxProfit) {
      maxProfit = profit;
      console.log(`New max profit: ${maxProfit}`);
    }
  }
}
return maxProfit;
